import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Quote: base price list, single main item, no modifiers ---
  it("quotes a plain sword for a new customer — base 100 G +10 % first insurance +5 G fee = 115 G", () => {
    expect(
      runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          {
            op: "quote",
            items: [{ type: "sword", material: "steel", enchantment: 3, cursed: false }],
          },
        ],
      }),
    ).toEqual({ results: [{ premium: 115 }] });
  });
  it.todo("quotes a plain amulet for a new customer — base 60 G +10 % +5 G = 71 G");
  it.todo("quotes a plain staff for a new customer — base 80 G +10 % +5 G = 93 G");
  it.todo("quotes a plain potion for a new customer — base 40 G +10 % +5 G = 49 G");

  // --- Quote: components ---
  it.todo("quotes a single rune — base 25 G +10 % +5 G = 33 G");
  it.todo("quotes a single moonstone — base 25 G +10 % +5 G = 33 G");
  it.todo("quotes two alike components separately — base 50 G +10 % +5 G = 60 G");
  it.todo("quotes a building block of 3 alike runes at the special base premium 60 G — +10 % +5 G = 71 G");
  it.todo("quotes 4 alike runes as one building block plus one single — base 60+25=85 G +10 % +5 G = 99 G");
  it.todo("does not form a building block from 3 unalike components (2 runes + 1 moonstone) — base 75 G +10 % +5 G = 88 G");

  // --- Quote: multiple items ---
  it.todo("sums base premiums of several main items — sword + potion = 140 G +10 % +5 G = 159 G");
  it.todo("quotes an empty item list — 0 G base +10 % +5 G = 5 G");

  // --- Quote: risk surcharges ---
  it.todo("adds a 50 % risk surcharge for a cursed sword — 150 G +10 % +5 G = 170 G");
  it.todo("adds a 30 % risk surcharge for a highly enchanted sword (enchantment 5) — 130 G +10 % +5 G = 148 G");
  it.todo("does not add the enchantment surcharge below level 5 (enchantment 4) — 100 G +10 % +5 G = 115 G");
  it.todo("combines cursed and high-enchantment surcharges on one item — 100 G × 1.5 × 1.3 = 195 G +10 % +5 G = 220 G");
  it.todo("applies surcharges per item, not to the whole quote — cursed sword + plain potion = 190 G +10 % +5 G = 214 G");

  // --- Quote: customer modifiers ---
  it.todo("grants a 20 % loyalty discount to a customer of 2 years — sword 100 G ×0.8 ×1.1 +5 G = 93 G");
  it.todo("grants no loyalty discount below 2 years (1 year) — 100 G ×1.1 +5 G = 115 G");
  it.todo("applies a 15 % contract discount to the second quote — sword 100 G ×0.85 +5 G = 90 G");
  it.todo("applies the 15 % contract discount to every quote after the first, and the 10 % first-insurance surcharge only to the first");
  it.todo("combines loyalty and contract discount on a loyal customer's second quote — 100 G ×0.8 ×0.85 +5 G = 73 G");

  // --- Quote: rounding ---
  it.todo("rounds the premium up to whole G in MHPCO's favour — amulet at 2 years: 60 ×0.8 ×1.1 = 52.8 → 53 +5 G = 58 G");

  // --- Claim: basics ---
  it.todo("pays a claim minus the 100 G deductible — 300 G damage on a plain amulet pays 200 G");
  it.todo("pays nothing when the damage does not exceed the deductible — 100 G damage pays 0 G");
  it.todo("applies the deductible once per damage event, not per damaged item — two 200 G damages in one incident pay 300 G");
  it.todo("reports the remaining cap after a claim — amulet policy cap 1200 G, 300 G damage pays 200 G, remainingCap 1000 G");

  // --- Claim: reimbursement rates ---
  it.todo("reimburses damage to an item with enchantment 8 at 50 % — 500 G damage → 250 G, minus 100 G deductible = 150 G");
  it.todo("reimburses damage to an item with enchantment 7 in full — 500 G damage minus 100 G = 400 G");
  it.todo("fully reimburses damage to an item of dragon material even at enchantment 8 — 500 G damage minus 100 G = 400 G");

  // --- Claim: cap ---
  it.todo("caps the payout at twice the insurance sum — sword policy cap 2000 G, 2500 G damage pays 2000 G, remainingCap 0 G");
  it.todo("caps the payout across several claims on the same policy and reports the shrinking remainingCap");
  it.todo("pays 0 G once the policy cap is exhausted");

  // --- Scenario / CLI integration ---
  it.todo("processes a scenario of quote then claim, returning one result per step in order");
  it.todo("routes a claim to the policy named by its zero-based step index");
});

