/** Rounds up to whole G (the MHPCO's favour), ignoring binary floating-point noise. */
const roundUpToWholeG = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));

const BASE_PREMIUM: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
const POLICY_FEE = 5;

const quote = (items: Item[]): QuoteResult => {
  const totalBasePremium = items.reduce((total, item) => total + BASE_PREMIUM[item.type], 0);
  const withFirstInsuranceSurcharge = totalBasePremium * (1 + FIRST_INSURANCE_SURCHARGE_RATE);
  return { premium: roundUpToWholeG(withFirstInsuranceSurcharge) + POLICY_FEE };
};

export const runScenario = (scenario: Scenario): ScenarioOutcome => {
  const results = scenario.steps.map((step) => {
    if (step.op === "quote") return quote(step.items);
    throw new Error("claim steps are not implemented yet");
  });
  return { results };
};

