  // --- Quote: customer modifiers ---
  it.todo("grants a 20 % loyalty discount to a customer of 2 years — sword 100 G ×0.8 ×1.1 +5 G = 93 G");
  it.todo("grants no loyalty discount below 2 years (1 year) — 100 G ×1.1 +5 G = 115 G");
