interface ScenarioState {
  quotesSoFar: number;
  /** Remaining payout cap of each policy, keyed by the step index that created it. */
  remainingCaps: Record<number, number>;
}

const INITIAL_STATE: ScenarioState = { quotesSoFar: 0, remainingCaps: {} };

const DEDUCTIBLE = 100;
const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;

const insuranceSumOf = (items: Item[]): number =>
  sum(items.map((item) => INSURANCE_VALUE[item.type]));

const claim = (incident: Incident, remainingCap: number): ClaimResult => {
  const damage = sum(incident.damages.map((damage) => damage.amount));
  const payout = Math.max(0, damage - DEDUCTIBLE);
  return { payout, remainingCap: remainingCap - payout };
};

const applyStep = (
  state: ScenarioState,
  step: Step,
  customer: Customer,
  stepIndex: number,
): { state: ScenarioState; result: Result } => {
  if (step.op === "quote") {
    const cap = CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSumOf(step.items);
    return {
      state: {
        quotesSoFar: state.quotesSoFar + 1,
        remainingCaps: { ...state.remainingCaps, [stepIndex]: cap },
      },
      result: quote(step.items, customer, state.quotesSoFar),
    };
  }
  const result = claim(step.incident, state.remainingCaps[step.policy]);
  return {
    state: {
      ...state,
      remainingCaps: { ...state.remainingCaps, [step.policy]: result.remainingCap },
    },
    result,
  };
};

