129	
130	const CONTRACT_DISCOUNT_RATE = -0.15;
131	
132	/**
133	 * Customer-level modifiers apply to the whole quote and compound. A customer's very
134	 * first insurance carries the assessment surcharge; every contract after it is
135	 * discounted instead. `previousQuotes` counts quotes already given to this customer.
136	 */
137	const customerMultiplierOf = (customer: Customer, previousQuotes: number): number => {
138	  const isFirstInsurance = previousQuotes === 0;
139	  return (
140	    rateFactor(isLoyal(customer), LOYALTY_DISCOUNT_RATE) *
141	    rateFactor(isFirstInsurance, FIRST_INSURANCE_SURCHARGE_RATE) *
142	    rateFactor(!isFirstInsurance, CONTRACT_DISCOUNT_RATE)
143	  );
144	};
145	
146	const quote = (items: Item[], customer: Customer, previousQuotes: number): QuoteResult => {
147	  const premiumBeforeFee =
148	    riskLoadedPremiumOf(items) * customerMultiplierOf(customer, previousQuotes);
149	  return { premium: roundUpToWholeG(premiumBeforeFee) + POLICY_FEE };
150	};
151	
152	/**
153	 * Steps are not independent: each one is answered in the light of the steps before it,
154	 * so the scenario is walked as a fold that threads what has happened so far.
155	 */
156	interface ScenarioState {
157	  quotesSoFar: number;
158	  /** Remaining payout cap of each policy, keyed by the step index that created it. */
159	  remainingCaps: Record<number, number>;
160	}
161	
162	const INITIAL_STATE: ScenarioState = { quotesSoFar: 0, remainingCaps: {} };
163	
164	const DEDUCTIBLE = 100;
165	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
166	
167	const insuranceSumOf = (items: Item[]): number =>
168	  sum(items.map((item) => INSURANCE_VALUE[item.type]));
169	
170	const claim = (incident: Incident, remainingCap: number): ClaimResult => {
171	  const damage = sum(incident.damages.map((damage) => damage.amount));
172	  const payout = Math.max(0, damage - DEDUCTIBLE);
173	  return { payout, remainingCap: remainingCap - payout };
174	};
175	
176	/** Records a policy's remaining cap, leaving the rest of the scenario state untouched. */
177	const withRemainingCap = (
178	  state: ScenarioState,
179	  policy: number,
180	  remainingCap: number,
181	): ScenarioState => ({
182	  ...state,
183	  remainingCaps: { ...state.remainingCaps, [policy]: remainingCap },
184	});
185	
186	const applyStep = (
187	  state: ScenarioState,
188	  step: Step,
189	  customer: Customer,
190	  stepIndex: number,
191	): { state: ScenarioState; result: Result } => {
192	  if (step.op === "quote") {
193	    const cap = CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSumOf(step.items);
194	    return {
195	      state: withRemainingCap({ ...state, quotesSoFar: state.quotesSoFar + 1 }, stepIndex, cap),
196	      result: quote(step.items, customer, state.quotesSoFar),
197	    };
198	  }
199	  const result = claim(step.incident, state.remainingCaps[step.policy]);
200	  return {
201	    state: withRemainingCap(state, step.policy, result.remainingCap),
202	    result,
203	  };
204	};
205	
206	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
207	  const results: Result[] = [];
208	  let state = INITIAL_STATE;
209	  for (const [stepIndex, step] of scenario.steps.entries()) {
210	    const stepOutcome = applyStep(state, step, scenario.customer, stepIndex);
211	    state = stepOutcome.state;
212	    results.push(stepOutcome.result);
213	  }
214	  return { results };
215	};

