/**
 * Steps are not independent: each one is answered in the light of the steps before it,
 * so the scenario is walked as a fold that threads what has happened so far.
 */
interface ScenarioState {
  quotesSoFar: number;
  /** Remaining payout cap of each policy, keyed by the step index that created it. */
  remainingCaps: Record<number, number>;
}

const INITIAL_STATE: ScenarioState = { quotesSoFar: 0, remainingCaps: {} };

const DEDUCTIBLE = 100;
const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;

const insuranceSumOf = (items: Item[]): number =>
  sum(items.map((item) => INSURANCE_VALUE[item.type]));

/** The deductible is borne by the incident as a whole, so all its damages are summed first. */
const totalDamageOf = (incident: Incident): number =>
  sum(incident.damages.map((damage) => damage.amount));

/** Draws the payout down against the policy's remaining cap, reporting what is left. */
const settleClaimAgainstCap = (incident: Incident, remainingCap: number): ClaimResult => {
  const payout = Math.max(0, totalDamageOf(incident) - DEDUCTIBLE);
  return { payout, remainingCap: remainingCap - payout };
};

/** Records a policy's remaining cap, leaving the rest of the scenario state untouched. */
const withRemainingCap = (
  state: ScenarioState,
  policy: number,
  remainingCap: number,
): ScenarioState => ({
  ...state,
  remainingCaps: { ...state.remainingCaps, [policy]: remainingCap },
});

const applyStep = (
  state: ScenarioState,
  step: Step,
  customer: Customer,
  stepIndex: number,
): { state: ScenarioState; result: Result } => {
  if (step.op === "quote") {
    const cap = CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSumOf(step.items);
    return {
      state: withRemainingCap({ ...state, quotesSoFar: state.quotesSoFar + 1 }, stepIndex, cap),
      result: quote(step.items, customer, state.quotesSoFar),
    };
  }
  const result = settleClaimAgainstCap(step.incident, state.remainingCaps[step.policy]);
  return {
    state: withRemainingCap(state, step.policy, result.remainingCap),
    result,
  };
};

